var DD_COVERS={"SM_10_07_COLE.webp": "https://cdn.prod.website-files.com/6a66d7a6f9d116b514a13ae1/6a66e61f1dabea02a089a958_SM_10_07_COLE.webp", "SM_10_06_JOBS.webp": "https://cdn.prod.website-files.com/6a66d7a6f9d116b514a13ae1/6a66e61f14427c7ab009ab87_SM_10_06_JOBS.webp", "SM_10_01_KEYES.webp": "https://cdn.prod.website-files.com/6a66d7a6f9d116b514a13ae1/6a66e61e44f46a1ffc5421ab_SM_10_01_KEYES.webp", "SM_10_09_DELL.webp": "https://cdn.prod.website-files.com/6a66d7a6f9d116b514a13ae1/6a66e6204d2ae840ef944797_SM_10_09_DELL.webp", "SM_10_12_SHRIVER.webp": "https://cdn.prod.website-files.com/6a66d7a6f9d116b514a13ae1/6a66e620e77ce54f28b00f1d_SM_10_12_SHRIVER.webp", "SM_11_02_CHAN.webp": "https://cdn.prod.website-files.com/6a66d7a6f9d116b514a13ae1/6a66e621901776d33b22791f_SM_11_02_CHAN.webp", "SM_09_07_BRANSON.webp": "https://cdn.prod.website-files.com/6a66d7a6f9d116b514a13ae1/6a66e5563a7bdd61c3f57593_SM_09_07_BRANSON.webp", "SM_10_08_JOHNSON.webp": "https://cdn.prod.website-files.com/6a66d7a6f9d116b514a13ae1/6a66e61f22bf946a016c20f8_SM_10_08_JOHNSON.webp", "SM_10_11_MANNINGS.webp": "https://cdn.prod.website-files.com/6a66d7a6f9d116b514a13ae1/6a66e6201dabea02a089aa11_SM_10_11_MANNINGS.webp", "SM_08_01_Kiyosaki.webp": "https://cdn.prod.website-files.com/6a66d7a6f9d116b514a13ae1/6a66e55557b738a7a0384417_SM_08_01_Kiyosaki.webp", "SM_08_04_OZ.webp": "https://cdn.prod.website-files.com/6a66d7a6f9d116b514a13ae1/6a66e555e77ce54f28afa6ca_SM_08_04_OZ.webp", "SM_10_05_MICHAELS.webp": "https://cdn.prod.website-files.com/6a66d7a6f9d116b514a13ae1/6a66e61ebbf0595728193975_SM_10_05_MICHAELS.webp", "SM_09_11_OSTEEN_barcode.webp": "https://cdn.prod.website-files.com/6a66d7a6f9d116b514a13ae1/6a66e61c7eed2e69a3002a34_SM_09_11_OSTEEN_barcode.webp", "SM_09_03_FOREMAN.webp": "https://cdn.prod.website-files.com/6a66d7a6f9d116b514a13ae1/6a66e55632c1b5d12231eb58_SM_09_03_FOREMAN.webp", "SM_08_06_Deutsch.webp": "https://cdn.prod.website-files.com/6a66d7a6f9d116b514a13ae1/6a66e555e77ce54f28afa6e7_SM_08_06_Deutsch.webp", "SM_09_02_Powell.webp": "https://cdn.prod.website-files.com/6a66d7a6f9d116b514a13ae1/6a66e5566ec51493e8c20979_SM_09_02_Powell.webp", "SM_11_01_HOWARD.webp": "https://cdn.prod.website-files.com/6a66d7a6f9d116b514a13ae1/6a66e621e123fb9285f82d0f_SM_11_01_HOWARD.webp", "SM_12_01_DOWNEY.webp": "https://cdn.prod.website-files.com/6a66d7a6f9d116b514a13ae1/6a66e6247eed2e69a3002cb2_SM_12_01_DOWNEY.webp", "SM_09_09_FOSTER_Barcode.webp": "https://cdn.prod.website-files.com/6a66d7a6f9d116b514a13ae1/6a66e61c5a1a5ea0057e80b9_SM_09_09_FOSTER_Barcode.webp", "SM_09_01_Robbins.webp": "https://cdn.prod.website-files.com/6a66d7a6f9d116b514a13ae1/6a66e556daf5e386ed5dd9a5_SM_09_01_Robbins.webp", "SM_11_04_SCHULTZ.webp": "https://cdn.prod.website-files.com/6a66d7a6f9d116b514a13ae1/6a66e6226c506c4f5d51d781_SM_11_04_SCHULTZ.webp", "SM_09_06_LANCE.webp": "https://cdn.prod.website-files.com/6a66d7a6f9d116b514a13ae1/6a66e55632c1b5d12231eb97_SM_09_06_LANCE.webp", "SM_10_02_RAMSEY.webp": "https://cdn.prod.website-files.com/6a66d7a6f9d116b514a13ae1/6a66e61e70b11505bd255a0d_SM_10_02_RAMSEY.webp", "SM_08_02_50.webp": "https://cdn.prod.website-files.com/6a66d7a6f9d116b514a13ae1/6a66e5554df7439ce7c715df_SM_08_02_50.webp", "SM_08_05_HAWK.webp": "https://cdn.prod.website-files.com/6a66d7a6f9d116b514a13ae1/6a66e55589d4dc60a5949544_SM_08_05_HAWK.webp", "JackWelch.webp": "https://cdn.prod.website-files.com/6a66d7a6f9d116b514a13ae1/6a66e5554df7439ce7c715ab_JackWelch.webp", "SM_13_05_FORD.webp": "https://cdn.prod.website-files.com/6a66d7a6f9d116b514a13ae1/6a66e62b14427c7ab009b4e1_SM_13_05_FORD.webp", "SM_12_07_TECHNOLOGY.webp": "https://cdn.prod.website-files.com/6a66d7a6f9d116b514a13ae1/6a66e628e123fb9285f83052_SM_12_07_TECHNOLOGY.webp", "SM_10_04_COLLINS.webp": "https://cdn.prod.website-files.com/6a66d7a6f9d116b514a13ae1/6a66e61ebbf0595728193948_SM_10_04_COLLINS.webp", "SM_09_08_FOX.webp": "https://cdn.prod.website-files.com/6a66d7a6f9d116b514a13ae1/6a66e556a4b0de80b8b501e2_SM_09_08_FOX.webp", "SM_10_03_HOPKINS.webp": "https://cdn.prod.website-files.com/6a66d7a6f9d116b514a13ae1/6a66e61eccabcac5f094e87e_SM_10_03_HOPKINS.webp", "SM_11_03_SCHWAB.webp": "https://cdn.prod.website-files.com/6a66d7a6f9d116b514a13ae1/6a66e6216c506c4f5d51d6fa_SM_11_03_SCHWAB.webp", "SM_09_10_SERENA_barcode.webp": "https://cdn.prod.website-files.com/6a66d7a6f9d116b514a13ae1/6a66e61c32c1b5d12232382b_SM_09_10_SERENA_barcode.webp", "SM_10_10_USHER.webp": "https://cdn.prod.website-files.com/6a66d7a6f9d116b514a13ae1/6a66e620d4f0219be4240398_SM_10_10_USHER.webp", "SM_09_12_DrPHIL.webp": "https://cdn.prod.website-files.com/6a66d7a6f9d116b514a13ae1/6a66e61d7eed2e69a3002a5e_SM_09_12_DrPHIL.webp", "SM_09_04_Maxwell.webp": "https://cdn.prod.website-files.com/6a66d7a6f9d116b514a13ae1/6a66e55632c1b5d12231eb6d_SM_09_04_Maxwell.webp", "SM_09_05_ORMAN.webp": "https://cdn.prod.website-files.com/6a66d7a6f9d116b514a13ae1/6a66e55632c1b5d12231eb82_SM_09_05_ORMAN.webp"};

